        "core_issue": "1) 사건 직접 쟁점 : 원고의 건강검진 당뇨 진단 누락이 보험계약 해지의 정당한 사유인 고지의무 위반에 해당하는지 여부.\n2) 약관/법리 쟁점 :\n  - 상법 제651조 및 제651조의2에 따른 '중요한 사항' 판단 기준 및 추정력.\n  - 고지의무 위반에 있어 '고의 또는 중대한 과실'의 의미.\n  - 고지의무 위반과 보험사고 발생 사이의 인과관계가 보험계약 해지의 요건인지 여부.\n  - 진단계약의 경우 보험자의 고지의무 위반 인지 또는 과실 여부가 해지권 행사에 미치는 영향.\n  - 보험설계사의 설명의무 위반 또는 고지 방해가 해지권 행사에 미치는 영향.",
